(function(){
  var STEPS=[0,0.5,1,1.5,2,2.5,3,3.5,4,5,6,7,8,9,10,11,12,14,16,20,24,28,32,36,40,44,48,52,56,60,64,72,80,96];
  var STEPSET={}; for(var si=0;si<STEPS.length;si++) STEPSET[STEPS[si]]=1;
  var ENUM={
    'display':{'block':'block','inline-block':'inline-block','inline':'inline','flex':'flex',
               'inline-flex':'inline-flex','grid':'grid','inline-grid':'inline-grid','none':'hidden',
               'table':'table','contents':'contents','flow-root':'flow-root'},
    'position':{'static':'static','fixed':'fixed','absolute':'absolute','relative':'relative','sticky':'sticky'},
    'flex-direction':{'row':'flex-row','row-reverse':'flex-row-reverse','column':'flex-col','column-reverse':'flex-col-reverse'},
    'flex-wrap':{'wrap':'flex-wrap','nowrap':'flex-nowrap','wrap-reverse':'flex-wrap-reverse'},
    'justify-content':{'flex-start':'justify-start','flex-end':'justify-end','center':'justify-center',
                       'space-between':'justify-between','space-around':'justify-around','space-evenly':'justify-evenly',
                       'start':'justify-start','end':'justify-end'},
    'align-items':{'flex-start':'items-start','flex-end':'items-end','center':'items-center',
                   'baseline':'items-baseline','stretch':'items-stretch','start':'items-start','end':'items-end'},
    'text-align':{'left':'text-left','center':'text-center','right':'text-right','justify':'text-justify'},
    'text-transform':{'uppercase':'uppercase','lowercase':'lowercase','capitalize':'capitalize','none':'normal-case'},
    'font-style':{'italic':'italic','normal':'not-italic'},
    'overflow':{'auto':'overflow-auto','hidden':'overflow-hidden','visible':'overflow-visible',
                'scroll':'overflow-scroll','clip':'overflow-clip'},
    'cursor':{'pointer':'cursor-pointer','default':'cursor-default','not-allowed':'cursor-not-allowed',
              'wait':'cursor-wait','text':'cursor-text','move':'cursor-move','grab':'cursor-grab'},
    'object-fit':{'contain':'object-contain','cover':'object-cover','fill':'object-fill',
                  'none':'object-none','scale-down':'object-scale-down'},
    'white-space':{'normal':'whitespace-normal','nowrap':'whitespace-nowrap','pre':'whitespace-pre',
                   'pre-wrap':'whitespace-pre-wrap','pre-line':'whitespace-pre-line'},
    'font-weight':{'100':'font-thin','200':'font-extralight','300':'font-light','400':'font-normal',
                   '500':'font-medium','600':'font-semibold','700':'font-bold','800':'font-extrabold',
                   '900':'font-black','normal':'font-normal','bold':'font-bold'},
    'text-decoration-line':{'underline':'underline','line-through':'line-through','none':'no-underline'},
    'visibility':{'visible':'visible','hidden':'invisible','collapse':'collapse'},
    'box-sizing':{'border-box':'box-border','content-box':'box-content'},
    'flex-grow':{'1':'grow','0':'grow-0'},
    'flex-shrink':{'1':'shrink','0':'shrink-0'}
  };
  var FONTSIZE={'12':'text-xs','14':'text-sm','16':'text-base','18':'text-lg','20':'text-xl','24':'text-2xl',
                '30':'text-3xl','36':'text-4xl','48':'text-5xl','60':'text-6xl','72':'text-7xl'};
  var RADIUS={'0':'rounded-none','2':'rounded-sm','4':'rounded','6':'rounded-md','8':'rounded-lg',
              '12':'rounded-xl','16':'rounded-2xl','24':'rounded-3xl','9999':'rounded-full'};
  var COLORS={'#fff':'white','#ffffff':'white','#000':'black','#000000':'black','white':'white',
              'black':'black','transparent':'transparent','currentcolor':'current','inherit':'inherit'};
  var SPACE={'padding':'p','padding-top':'pt','padding-right':'pr','padding-bottom':'pb','padding-left':'pl',
             'margin':'m','margin-top':'mt','margin-right':'mr','margin-bottom':'mb','margin-left':'ml',
             'gap':'gap','row-gap':'gap-y','column-gap':'gap-x','width':'w','height':'h',
             'min-width':'min-w','min-height':'min-h','max-width':'max-w','max-height':'max-h',
             'top':'top','right':'right','bottom':'bottom','left':'left','inset':'inset',
             'flex-basis':'basis'};

  function px(v){
    v=String(v).trim();
    var m=v.match(/^(-?[\d.]+)px$/); if(m) return parseFloat(m[1]);
    var r=v.match(/^(-?[\d.]+)rem$/); if(r) return parseFloat(r[1])*16;
    if(v==='0') return 0;
    return null;
  }
  function spaceToken(v){
    var n=px(v);
    if(n===null){
      if(v==='auto') return 'auto';
      if(v==='100%') return 'full';
      if(v==='100vw'||v==='100vh') return 'screen';
      if(v==='50%') return '1/2';
      if(v==='fit-content') return 'fit';
      return null;
    }
    var neg=n<0; var a=Math.abs(n);
    if(a===1) return (neg?'-':'')+'px';
    var st=a/4;
    if(STEPSET[st]) return (neg?'-':'')+String(st);
    return null;
  }
  function normColor(v){
    var k=String(v).trim().toLowerCase();
    if(COLORS[k]) return COLORS[k];
    return null;
  }
  function parseDecls(text){
    var out=[],raw=String(text||'').replace(/\/\*[\s\S]*?\*\//g,'');
    var body=raw;
    var b=raw.indexOf('{');
    if(b>=0){ var e=raw.lastIndexOf('}'); body=raw.slice(b+1, e<0?raw.length:e); }
    var parts=body.split(';');
    for(var i=0;i<parts.length;i++){
      var p=parts[i]; if(!p.trim()) continue;
      var c=p.indexOf(':'); if(c<0) continue;
      out.push([p.slice(0,c).trim().toLowerCase(), p.slice(c+1).trim().replace(/\s*!important$/,'')]);
    }
    return out;
  }
  function cssToTw(text){
    var decls=parseDecls(text);
    if(!decls.length) return {error:'未解析到 CSS 声明'};
    var cls=[],un=[];
    for(var i=0;i<decls.length;i++){
      var prop=decls[i][0],val=decls[i][1],lv=val.toLowerCase();
      if(ENUM[prop]&&ENUM[prop][lv]){ cls.push(ENUM[prop][lv]); continue; }
      if(prop==='font-size'){ var fp=px(val); cls.push((fp!==null&&FONTSIZE[String(fp)])||('text-['+val+']')); continue; }
      if(prop==='border-radius'){ var rp=px(val); cls.push((rp!==null&&RADIUS[String(rp)])||('rounded-['+val+']')); continue; }
      if(prop==='color'){ var c1=normColor(val); cls.push('text-'+(c1||'['+val+']')); continue; }
      if(prop==='background-color'||prop==='background'){ var c2=normColor(val); cls.push('bg-'+(c2||'['+val+']')); continue; }
      if(prop==='border-color'){ var c3=normColor(val); cls.push('border-'+(c3||'['+val+']')); continue; }
      if(prop==='opacity'){ var o=parseFloat(val); cls.push('opacity-'+Math.round(o*100)); continue; }
      if(prop==='z-index'){ cls.push('z-'+val); continue; }
      if(prop==='line-height'){ var lp=px(val); cls.push(lp!==null?('leading-['+val+']'):('leading-['+val+']')); continue; }
      if(prop==='letter-spacing'){ cls.push('tracking-['+val+']'); continue; }
      if(prop==='border-width'){ var bp=px(val); cls.push(bp===1?'border':('border-'+(bp===null?'['+val+']':bp))); continue; }
      if(prop==='box-shadow'){ cls.push(lv==='none'?'shadow-none':'shadow'); continue; }
      if(SPACE[prop]){
        var pieces=val.split(/\s+/);
        if(pieces.length===2&&(prop==='padding'||prop==='margin')){
          var pre=(prop==='padding')?'p':'m';
          var ty=spaceToken(pieces[0]),tx=spaceToken(pieces[1]);
          cls.push(ty!==null?(pre+'y-'+ty):(pre+'y-['+pieces[0]+']'));
          cls.push(tx!==null?(pre+'x-'+tx):(pre+'x-['+pieces[1]+']'));
          continue;
        }
        var t=spaceToken(pieces[0]);
        var pfx=SPACE[prop];
        if(t===null){ cls.push(pfx+'-['+val+']'); }
        else if(t.charAt(0)==='-'){ cls.push('-'+pfx+'-'+t.slice(1)); }
        else { cls.push(pfx+'-'+t); }
        continue;
      }
      un.push(prop);
      cls.push('['+prop+':'+val.replace(/\s/g,'_')+']');
    }
    return {value:{classes:cls.join(' '),count:cls.length,unknown:un}};
  }

  var REV=null;
  function buildRev(){
    if(REV) return REV;
    REV={};
    for(var prop in ENUM){ var m=ENUM[prop];
      for(var v in m){ if(!REV[m[v]]) REV[m[v]]=[prop,v]; } }
    for(var f in FONTSIZE) REV[FONTSIZE[f]]=['font-size',f+'px'];
    for(var rr in RADIUS) REV[RADIUS[rr]]=['border-radius',(rr==='9999'?'9999px':rr+'px')];
    return REV;
  }
  var SPACEREV=null;
  function buildSpaceRev(){
    if(SPACEREV) return SPACEREV;
    SPACEREV={};
    for(var prop in SPACE) SPACEREV[SPACE[prop]]=prop;
    SPACEREV['px']='padding-left|padding-right';
    SPACEREV['py']='padding-top|padding-bottom';
    SPACEREV['mx']='margin-left|margin-right';
    SPACEREV['my']='margin-top|margin-bottom';
    return SPACEREV;
  }
  function remOf(tok){
    if(tok==='px') return '1px';
    if(tok==='auto') return 'auto';
    if(tok==='full') return '100%';
    if(tok==='screen') return '100vh';
    var n=parseFloat(tok);
    if(isNaN(n)) return null;
    if(n===0) return '0';
    return (n*0.25)+'rem';
  }
  function twToCss(classes){
    var list=String(classes||'').trim().split(/\s+/).filter(Boolean);
    if(!list.length) return {error:'请输入 Tailwind class'};
    var rev=buildRev(),sr=buildSpaceRev(),out=[],un=[];
    for(var i=0;i<list.length;i++){
      var c=list[i],neg=false;
      if(c.charAt(0)==='-'){ neg=true; c=c.slice(1); }
      if(rev[c]){ out.push([rev[c][0],rev[c][1]]); continue; }
      var arb=c.match(/^(-?[a-z-]+)-\[(.+)\]$/);
      if(arb){
        var ap=arb[1],av=arb[2].replace(/_/g,' ');
        if(ap==='text') out.push(['color',av]);
        else if(ap==='bg') out.push(['background-color',av]);
        else if(sr[ap]) pushSpace(out,sr[ap],av);
        else out.push([ap,av]);
        continue;
      }
      var m=c.match(/^(-?[a-z]+(?:-[a-z]+)*)-([0-9.\/]+|px|auto|full|screen)$/);
      if(m&&sr[m[1]]){
        var v=remOf(m[2]);
        if(v!==null){ pushSpace(out,sr[m[1]],(neg?'-':'')+v); continue; }
      }
      if(/^opacity-(\d+)$/.test(c)){ out.push(['opacity',String(parseInt(c.slice(8),10)/100)]); continue; }
      if(/^z-(\d+)$/.test(c)){ out.push(['z-index',c.slice(2)]); continue; }
      if(c==='border'){ out.push(['border-width','1px']); continue; }
      if(/^border-(\d+)$/.test(c)){ out.push(['border-width',c.slice(7)+'px']); continue; }
      if(c==='shadow'){ out.push(['box-shadow','0 1px 3px rgb(0 0 0 / 0.1)']); continue; }
      if(c==='text-white'||c==='text-black'){ out.push(['color',c.slice(5)]); continue; }
      if(c==='bg-white'||c==='bg-black'){ out.push(['background-color',c.slice(3)]); continue; }
      un.push(c);
    }
    if(!out.length) return {error:'无法识别任何 class：'+un.join(' ')};
    var css=out.map(function(d){return d[0]+': '+d[1]+';';}).join('\n');
    return {value:{css:css,count:out.length,unknown:un}};
  }
  function pushSpace(out,prop,val){
    var ps=prop.split('|');
    for(var i=0;i<ps.length;i++) out.push([ps[i],val]);
  }

  var API={cssToTw:cssToTw,twToCss:twToCss,parseDecls:parseDecls,spaceToken:spaceToken,px:px};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__TwForge__=API;
})();
